sys_ui_action.script:
function confirmStartSync() {
    var gm = new GlideModal('', false, 700);
    gm.setTitle('Confirm sync');

    top.window.startSyncConfirm = function(answer) {
        gm.destroy();

        if (answer === 'yes') {
            gsftSubmit(null, g_form.getFormElement(), 'start_sync');
        }

        return false;
    };

    var html =
        '<div style="padding: 8px 4px 4px 4px; font-size: 16px; line-height: 1.5;">' +
            '<p>Start a sync to the PCE now, without waiting for the scheduled run?</p>' +
            '<p>Workloads matched by active inclusion sync filters will be created or updated ' +
            'on the PCE. Workloads whose <b>Known to PCE</b> is <i>unknown</i> are ' +
            '<b>created</b>; managed and unmanaged ones are updated.</p>' +
            '<p>Only workloads with <b>Conflicts = true</b> are synced. If none are flagged, ' +
            'the job will finish successfully having done nothing.</p>' +
            '<div style="display:flex; justify-content:flex-end; gap:12px; margin-top:20px;">' +
                '<button style="flex: 1; width: 100%" class="btn btn-default" onclick="top.window.startSyncConfirm(\'no\'); return false;">Cancel</button>' +
                '<button style="flex: 1; width: 100%" class="btn btn-primary" onclick="top.window.startSyncConfirm(\'yes\'); return false;">Yes</button>' +
            '</div>' +
        '</div>';

    gm.renderWithContent(html);
    return false;
}

// Server half: a trigger, and nothing else.
//
// Deliberately identical in shape to `Start Workload Deletion`, with one difference: there is no
// preview gate. Deletion demands a fresh DELETION-PREVIEW- attachment because it is
// non-reversible; sync is re-runnable, so the gate would be ceremony.
//
// DEVELOPMENT AID. This exists so a sync can be triggered on demand instead of waiting for the
// PCE Configuration's own schedule. It does not replace the scheduled run and adds nothing to it
// -- it creates the same job record that the scheduler would and raises an event that lands in
// the same IllumioAutoSyncWithPCE.process(). Remove it, its Event Registry entry and its Script
// Action before this ships.
if (typeof window === 'undefined') {
    // Declared inside the server guard for the same reason gs.include is: this Script
    // field is evaluated in the browser too, for the client half above, and IllumioLogger
    // is a server Script Include. At the top of the file it threw a ReferenceError on
    // every form load and stopped the form rendering.
    var illumioLogger = new IllumioLogger(null, 'Start Sync');

    // Inside the server guard, not at the top of the file. This Script field is evaluated in
    // the browser too, for the client half above, and `gs` does not exist there -- a
    // top-level gs.include would throw a ReferenceError and kill the onclick handler.
    gs.include("IllumioConstants");

    var configSysId = current.getUniqueValue();
    var redirectUrl = current.getTableName() + '.do?sys_id=' + configSysId;

    /**
     * Is this event name in the Event Registry?
     *
     * sysevent_register is a global table, so a scoped read of it can be refused depending on
     * cross-scope privileges. A refusal is not evidence the event is missing, so it is treated as
     * "cannot tell" and the sync is allowed to proceed -- the point of this check is to catch the
     * common case where the entry was simply never created, not to add a new way to block.
     *
     * @param {String} eventName Fully qualified event name
     * @returns {Boolean} False only when the registry could be read and the event was absent
     */
    var eventIsRegistered = function(eventName) {
        try {
            var registryGr = new GlideRecord('sysevent_register');
            if (!registryGr.isValid()) {
                return true;
            }
            registryGr.addQuery('event_name', eventName);
            registryGr.setLimit(1);
            registryGr.query();
            return registryGr.hasNext();
        } catch (checkEx) {
            illumioLogger.warn('Could not read sysevent_register, proceeding anyway: ' + checkEx);
            return true;
        }
    };

    try {
        var utils = new IllumioUtils();
        var runningJob = utils.getRunningJob(configSysId);

        if (runningJob) {
            // A genuine guard: nothing has been queried or written at this point.
            //
            // Scoped to this PCE Configuration. It used to match any Illumio job anywhere,
            // justified by sync, deletion and preview all writing to the shared payload tables
            // and all driving the same MID Server. Both of those really were unsafe -- the
            // payload sweep deleted other jobs' rows and the MID temp-file sweep deleted other
            // runs' part-written files -- and both are fixed at the source now, so the wide
            // scope bought nothing beyond blocking configuration B while A ran. See
            // getRunningJob.
            gs.addErrorMessage(utils.describeRunningJob(runningJob));
            action.setRedirectURL(redirectUrl);

        } else if (!eventIsRegistered('x_illu2_illumio.start_sync')) {
            // Pre-flight, and the reason this button "did nothing". gs.eventQueueScheduled on an
            // unregistered event is a no-op that returns nothing and throws nothing: the job
            // record was inserted as `running`, the UI said "Sync job started", and the job then
            // sat there forever. Worse, getRunningJob matched ANY running job at the time, so
            // that one stuck record went on to refuse every Start Sync, Start Workload Deletion
            // and preview on the instance. The guard is per-configuration now, so a repeat would
            // strand one configuration rather than all of them -- still worth refusing here,
            // before a job record exists, rather than relying on that.
            //
            // Event Registry rows live in sysevent_register, which is not in this repository --
            // so pushing the UI Action, the Script Action and this script is not enough and
            // nothing in source control says so. Checked rather than assumed, and refused before
            // a job record exists so there is nothing left stuck.
            gs.addErrorMessage('Sync not started: the event "x_illu2_illumio.start_sync" is not ' +
                'in the Event Registry, so nothing would have picked the job up. Create a ' +
                'System Policy > Events > Registry entry with Event name ' +
                '"x_illu2_illumio.start_sync" and Table ' +
                'TABLE_SCHEDULED_JOBS, and a Script Action named "StartSync" ' +
                'bound to it.');
            action.setRedirectURL(redirectUrl);

        } else {
            var jobGr = new GlideRecordSecure(TABLE_SCHEDULED_JOBS);
            jobGr.initialize();
            jobGr.job_owner = gs.getUser().getID();
            jobGr.job_type = JOB_TYPE_DATA_SYNC;
            jobGr.job_status = JOB_STATUS_RUNNING;
            jobGr.job_started = new GlideDateTime();
            jobGr.current_operation = 'Synchronizing workloads to PCE';
            jobGr.illumio_pce_configuration = configSysId;
            jobGr.logs = 'Sync requested manually. Discovery skipped.';
            var jobSysId = jobGr.insert();
            // From here on the job record exists, so anything this action logs -- including
            // an exception out of the block below -- lands under the same job id the
            // scheduler half will use.
            illumioLogger.setContext(jobSysId);

            if (gs.nil(jobSysId)) {
                gs.addErrorMessage('Failed to create scheduled job for sync.');
            } else {
                // Same handoff deletion and discovery use: the event is raised here, the Script
                // Action picks it up in the scheduler. process() reads the configuration and the
                // owner off the job record, so the event only has to carry the job sys_id.
                gs.eventQueueScheduled('x_illu2_illumio.start_sync',
                    jobGr, jobSysId, '', new GlideDateTime());

                gs.addInfoMessage('Sync job started. Track progress in Scheduled Jobs.');
            }

            action.setRedirectURL(redirectUrl);
        }
    } catch (ex) {
        illumioLogger.error('Exception: ' + ex);
        gs.addErrorMessage('Error starting sync: ' + ex);
        action.setRedirectURL(redirectUrl);
    }
}
